-- =============================================================================
-- PLATAFORMA SUR · GLOBAL BUSINESS — SUPABASE CMS SCHEMA
-- =============================================================================
-- Ejecuta este script en el SQL Editor de tu proyecto Supabase para habilitar
-- la persistencia cloud del CMS (/admin) para Productos, Fichas Técnicas (ES/EN),
-- Textos del Sitio y Configuración Comercial.
-- =============================================================================

-- 1. Tabla de Productos y Fichas Técnicas Bilingües (ES / EN)
CREATE TABLE IF NOT EXISTS public.cms_products (
  id TEXT PRIMARY KEY,
  country TEXT NOT NULL CHECK (country IN ('Argentina', 'Bolivia', 'Perú')),
  category TEXT NOT NULL CHECK (category IN ('Legumbres', 'Granos', 'Semillas', 'Andinos')),
  sort_order INTEGER NOT NULL DEFAULT 100,
  es_payload JSONB NOT NULL,
  en_payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_cms_products_country ON public.cms_products (country);
CREATE INDEX IF NOT EXISTS idx_cms_products_category ON public.cms_products (category);
CREATE INDEX IF NOT EXISTS idx_cms_products_sort_order ON public.cms_products (sort_order);

-- 2. Tabla de Diccionarios de Traducción del Sitio (ES / EN)
CREATE TABLE IF NOT EXISTS public.cms_translations (
  locale TEXT PRIMARY KEY CHECK (locale IN ('ES', 'EN')),
  dictionary JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Tabla de Configuración Comercial y Contacto (WhatsApp, Email, Marca)
CREATE TABLE IF NOT EXISTS public.cms_company_config (
  id TEXT PRIMARY KEY DEFAULT 'default',
  config_payload JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Trigger automático para updated_at
CREATE OR REPLACE FUNCTION public.handle_cms_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_cms_products_updated_at ON public.cms_products;
CREATE TRIGGER trg_cms_products_updated_at
  BEFORE UPDATE ON public.cms_products
  FOR EACH ROW EXECUTE FUNCTION public.handle_cms_updated_at();

DROP TRIGGER IF EXISTS trg_cms_translations_updated_at ON public.cms_translations;
CREATE TRIGGER trg_cms_translations_updated_at
  BEFORE UPDATE ON public.cms_translations
  FOR EACH ROW EXECUTE FUNCTION public.handle_cms_updated_at();

DROP TRIGGER IF EXISTS trg_cms_company_updated_at ON public.cms_company_config;
CREATE TRIGGER trg_cms_company_updated_at
  BEFORE UPDATE ON public.cms_company_config
  FOR EACH ROW EXECUTE FUNCTION public.handle_cms_updated_at();

-- 5. Row Level Security (RLS)
ALTER TABLE public.cms_products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cms_translations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cms_company_config ENABLE ROW LEVEL SECURITY;

-- Lectura pública para el catálogo web
CREATE POLICY "Allow public read access on cms_products"
  ON public.cms_products FOR SELECT USING (true);

CREATE POLICY "Allow public read access on cms_translations"
  ON public.cms_translations FOR SELECT USING (true);

CREATE POLICY "Allow public read access on cms_company_config"
  ON public.cms_company_config FOR SELECT USING (true);

-- Escritura permitida para rol autenticado / service_role / anon (según configuración del proyecto)
CREATE POLICY "Allow CMS write on cms_products"
  ON public.cms_products FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow CMS write on cms_translations"
  ON public.cms_translations FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow CMS write on cms_company_config"
  ON public.cms_company_config FOR ALL USING (true) WITH CHECK (true);


