VALUES ('quinua-negra-pe', 'Perú', 'Andinos', 160, '{"id":"quinua-negra-pe","name":"Quinua Negra","scientific":"Chenopodium quinoa Willd.","country":"Perú","region":"Puno y Ayacucho","category":"Andinos","image":"/images/products/quinua-negra.jpg","shortDescription":"Quinua negra peruana variedad Collana, grano oscuro y crocante, premium para mercados gourmet y health-food.","description":"Quinua negra peruana variedad Collana, grano de color oscuro y textura crocante. Producto premium para mercados gourmet y health-food. Lavada, libre de saponina residual y lista para consumo.","physical":{"color":"Negro con leves matices marrón","smellTaste":"Característico, ligeramente más terroso","appearance":"Grano entero, uniforme y brillante"},"qualityParameters":[{"label":"Pureza","value":"≥ 99.9%"},{"label":"Materia extraña","value":"≤ 0.1%"},{"label":"Saponina","value":"Lavada (residual)"}],"chemicalParameters":[{"label":"Humedad","value":"≤ 11%"},{"label":"Proteína","value":"≥ 13%"}],"condition":"Lavada, zarandeada y seleccionada. Libre de contaminantes visibles. Apta para consumo humano.","observation":"Producto apto para consumo humano. Garantizamos trazabilidad desde el origen, rotación de cosecha actual y frescura inmediata.","varieties":["Collana Negra"],"calibers":["1.7 mm+","1.9 mm+"],"moisture":"Máx. 11%","qualityParams":["Saponina: lavada","Pureza: 99.9%","Materia extraña: máx. 0.1%"],"packaging":["Bolsas PP 25 kg","Big bags 1.000 kg"],"harvestSeason":"Abril a Junio","certifications":["HACCP","Orgánico USDA/EU","Kosher","Gluten-free","Fair Trade"],"incoterms":["FOB","CIF","CFR"],"uses":["Consumo directo","Mix andinos","Snacks saludables","Industria nutracéutica"]}'::jsonb, '{"name":"Black Quinoa","region":"Puno and Ayacucho","shortDescription":"Peruvian black quinoa, Collana variety, dark crunchy grain, premium for gourmet and health-food markets.","description":"Peruvian black quinoa, Collana variety, dark grain with crunchy texture. Premium product for gourmet and health-food markets. Washed, free of residual saponin and ready to eat.","physical":{"color":"Black with subtle brown tones","smellTaste":"Characteristic, slightly earthier","appearance":"Whole, uniform and bright grain"},"qualityParameters":[{"label":"Purity","value":"≥ 99.9%"},{"label":"Foreign matter","value":"≤ 0.1%"},{"label":"Saponin","value":"Washed (residual)"}],"chemicalParameters":[{"label":"Moisture","value":"≤ 11%"},{"label":"Protein","value":"≥ 13%"}],"condition":"Washed, sieved and selected. Free of visible contaminants. Suitable for human consumption.","observation":"Suitable for human consumption. We guarantee traceability from origin, current crop rotation and immediate freshness.","varieties":["Black Collana"],"packaging":["25 kg PP bags","1,000 kg big bags"],"harvestSeason":"April to June","certifications":["HACCP","Organic USDA/EU","Kosher","Gluten-free","Fair Trade"],"uses":["Direct consumption","Andean mixes","Healthy snacks","Nutraceutical industry"]}'::jsonb)
ON CONFLICT (id) DO UPDATE SET country = EXCLUDED.country, category = EXCLUDED.category, es_payload = EXCLUDED.es_payload, en_payload = EXCLUDED.en_payload, updated_at = NOW();

INSERT INTO public.cms_products (id, country, category, sort_order, es_payload, en_payload)
VALUES ('mani-runner-pe', 'Perú', 'Granos', 170, '{"id":"mani-runner-pe","name":"Maní Runner","scientific":"Arachis hypogaea","country":"Perú","region":"Costa norte y selva","category":"Granos","image":"/images/products/mani-runner.jpg","shortDescription":"Maní variedad Runner en grano crudo entero con piel marrón-beige, libre de impurezas y residuos, ideal para industria de snacks, confitería y aceite.","description":"Granos enteros de maní de la variedad Runner provenientes del fruto de la planta Arachis hypogaea, sin cápsula y con su piel interna intacta. Producto exento de impurezas, libre de sustancias tóxicas y residuos de pesticidas dentro de los límites permitidos por la normativa internacional (UE y Codex Alimentarius). Apto para industria de snacks, confitería, panificación y aceite.","physical":{"color":"Piel marrón-beige; al partir el grano, color dorado homogéneo","smellTaste":"Característico, libre de rancidez y de cualquier olor o sabor extraño","appearance":"Grano entero con película protectora interna (piel), sin hongo interno"},"qualityParameters":[{"label":"Hongos internos","value":"Máx. 0.1%"},{"label":"Hongos externos","value":"Máx. 1.0%"},{"label":"Rancios","value":"Máx. 3.0%"},{"label":"Picados","value":"Máx. 3.0%"},{"label":"Arrugados","value":"Máx. 6.0%"},{"label":"Germinados","value":"Máx. 1.0%"},{"label":"Pelados","value":"Máx. 6.0%"},{"label":"Quebrados y partidos (mitades)","value":"Máx. 3.0%"},{"label":"Sucios","value":"Máx. 5.0%"},{"label":"Otras variedades","value":"Máx. 0.5%"},{"label":"Impurezas vegetales / minerales / cuerpos extraños / infestados","value":"Ausencia"}],"chemicalParameters":[{"label":"Humedad","value":"Máx. 8.0%"},{"label":"Grasa","value":"Mín. 45.0%"},{"label":"Aflatoxinas totales","value":"Máx. 10 ppb"},{"label":"Acidez","value":"Máx. 0.5%"},{"label":"Índice de peróxido","value":"Máx. 5 meq/kg"},{"label":"Metales pesados","value":"Según Codex Alimentarius"},{"label":"E. coli","value":"< 10 ufc/g"},{"label":"Mohos y levaduras","value":"< 100 ufc/g"},{"label":"Salmonella sp.","value":"Ausencia en 25 g"}],"condition":"Grano crudo, entero, con piel interna. Limpio, calibrado y seleccionado. Libre de plagas vivas, cuerpos extraños y contaminantes visibles. Apto para consumo humano.","observation":"Residuos de pesticidas dentro de los LMR de la Unión Europea (Reglamento UE 2015/845) y del Codex Alimentarius FAO/OMS. Trazabilidad garantizada desde el origen.","varieties":["Runner natural con piel"],"calibers":["38/42","40/50","50/60","55/70","60/70 (ideal)","70/80"],"moisture":"Máx. 8%","qualityParams":["Aflatoxinas totales: máx. 10 ppb","Grasa: mín. 45%","Acidez: máx. 0.5%","Tolerancia fuera de calibre: ±1%"],"packaging":["Sacos de polipropileno de primer uso","Big bags 1.000 kg","Almacenamiento sobre paletas, lugar limpio, fresco y seco (25-30°C, HR 75%)"],"harvestSeason":"Abril a Julio","certifications":["HACCP","BRC","SENASA Perú","Codex Alimentarius","UE 2015/845"],"incoterms":["FOB","CIF","CFR"],"uses":["Snacks tostados y salados","Confitería","Panificación","Industria del aceite"]}'::jsonb, '{"name":"Runner Peanut","region":"Northern coast and rainforest","shortDescription":"Runner variety raw whole peanut kernels with brown-beige skin, free of impurities and residues, ideal for snacks, confectionery and oil industries.","description":"Whole peanut kernels of the Runner variety from the Arachis hypogaea plant, without shell and with intact inner skin. Free of impurities, toxic substances and pesticide residues within the limits set by international regulations (EU and Codex Alimentarius). Suitable for snacks, confectionery, bakery and oil industries.","physical":{"color":"Brown-beige skin; uniform golden color when split","smellTaste":"Characteristic, free of rancidity and any foreign odor or flavor","appearance":"Whole kernel with inner protective skin, no internal mold"},"qualityParameters":[{"label":"Internal mold","value":"Max. 0.1%"},{"label":"External mold","value":"Max. 1.0%"},{"label":"Rancid","value":"Max. 3.0%"},{"label":"Pitted","value":"Max. 3.0%"},{"label":"Shriveled","value":"Max. 6.0%"},{"label":"Sprouted","value":"Max. 1.0%"},{"label":"Peeled","value":"Max. 6.0%"},{"label":"Broken and split (halves)","value":"Max. 3.0%"},{"label":"Dirty","value":"Max. 5.0%"},{"label":"Other varieties","value":"Max. 0.5%"},{"label":"Plant/mineral impurities, foreign bodies, infested","value":"Absent"}],"chemicalParameters":[{"label":"Moisture","value":"Max. 8.0%"},{"label":"Fat","value":"Min. 45.0%"},{"label":"Total aflatoxins","value":"Max. 10 ppb"},{"label":"Acidity","value":"Max. 0.5%"},{"label":"Peroxide value","value":"Max. 5 meq/kg"},{"label":"Heavy metals","value":"Per Codex Alimentarius"},{"label":"E. coli","value":"< 10 cfu/g"},{"label":"Molds and yeasts","value":"< 100 cfu/g"},{"label":"Salmonella sp.","value":"Absent in 25 g"}],"condition":"Raw, whole kernel with inner skin. Clean, sized and selected. Free of live pests, foreign bodies and visible contaminants. Suitable for human consumption.","observation":"Pesticide residues within EU MRLs (Regulation EU 2015/845) and Codex Alimentarius FAO/WHO. Traceability guaranteed from origin.","varieties":["Natural Runner with skin"],"calibers":["38/42","40/50","50/60","55/70","60/70 (ideal)","70/80"],"packaging":["First-use polypropylene bags","1,000 kg big bags","Stored on pallets in a clean, cool, dry place (25-30°C, 75% RH)"],"harvestSeason":"April to July","certifications":["HACCP","BRC","SENASA Peru","Codex Alimentarius","EU 2015/845"],"uses":["Roasted and salted snacks","Confectionery","Bakery","Oil industry"]}'::jsonb)
